// Consulta manual realizada em 2026-09-18 na tabela EAP do Supabase.
const ids = [32, 51, 66, 73, 86, 87, 88, 89, 90, 94, 110, 114, 115, 121, 127];
return ids.map(id_eap => ({ json: { id_eap } }));

const corpo = $json.data ?? $json.body?.data ?? $json.body ?? $json;
if (!corpo || !Array.isArray(corpo.tarefas)) throw new Error('Resposta invalida para id_eap ' + $('Loop id_eap (1 por vez)1').item.json.id_eap);

// --- normalizacao: o mesmo payload alimenta Supabase e MySQL ---
const vazio = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
const n = v => { if (vazio(v)) return null; const x = Number(typeof v === 'string' ? v.trim().replace(',', '.') : v); return Number.isFinite(x) ? x : null; };
const s = (v, max) => { if (vazio(v)) return null; const t = String(v).trim(); return t.length > max ? t.slice(0, max) : t; };
const d = v => { if (vazio(v)) return null; const t = String(v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null; };

// os limites de texto abaixo sao o tamanho das colunas em painelmse.eap_tarefas
const rows = corpo.tarefas.map(t => ({
  id: n(t.id),
  id_obra: n(corpo.id_obra),
  nome_obra: s(corpo.nome_obra, 120),
  id_eap: n(corpo.id_eap),
  edt: s(t.edt, 60),
  tarefa: s(t.tarefa, 255),
  disciplina: s(t.disciplina, 120),
  local: s(t.local, 160),
  unidade: s(t.unidade, 20),
  qtd: n(t.qtd),
  saldo_qtd: n(t.saldo_qtd),
  efetivo_previsto: n(t.efetivo_previsto),
  ponderacao_reais: n(t.ponderacao_reais),
  ponderacao_hht: n(t.ponderacao_hht),
  data_inicio: d(t.data_inicio),
  data_termino: d(t.data_termino),
  data_inicio_reprogramado: d(t.data_inicio_reprogramado),
  data_termino_reprogramado: d(t.data_termino_reprogramado),
  encarregado_nome: s(t.encarregado_nome, 120),
  avanco_atual: n(t.avanco_atual),
  desvio: n(t.desvio),
  meta_diaria: n(t.meta_diaria),
  avanco_diario: n(t.avanco_diario),
  hht_consumido: n(t.hht_consumido),
  status_qualidade: s(t.status_qualidade, 30)
})).filter(r => r.id != null);

// --- SQL para MySQL: painelmse.eap_tarefas (PK = id) ---
const MODELO = { id:1, id_obra:1, nome_obra:1, id_eap:1, edt:1, tarefa:1, disciplina:1, local:1, unidade:1, qtd:1, saldo_qtd:1, efetivo_previsto:1, ponderacao_reais:1, ponderacao_hht:1, data_inicio:1, data_termino:1, data_inicio_reprogramado:1, data_termino_reprogramado:1, encarregado_nome:1, avanco_atual:1, desvio:1, meta_diaria:1, avanco_diario:1, hht_consumido:1, status_qualidade:1 };
const CHAVE = ['id'];
const q = String.fromCharCode(96);
const COLUNAS = Object.keys(MODELO);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\x00/g, '') + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));
const colsSql = COLUNAS.map(c => q + c + q).join(',');
const tuplas = rows.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const updSql = COLUNAS.filter(c => !CHAVE.includes(c)).map(c => q + c + q + ' = VALUES(' + q + c + q + ')').join(', ');
const sqlMySql = rows.length ? 'INSERT INTO eap_tarefas (' + colsSql + ') VALUES ' + tuplas + ' ON DUPLICATE KEY UPDATE ' + updSql : 'SELECT 1';
return [{ json: { rows, sqlMySql, total: rows.length } }];
